enum class Lampu { Merah, Kuning, Hijau };

Lampu berikutnya(Lampu sekarang) {
    switch (sekarang) {
        case Lampu::Merah: return Lampu::Hijau;
        case Lampu::Hijau: return Lampu::Kuning;
        default: return Lampu::Merah;
    }
}

