    cin >> kata;
    auto lampu = Lampu::Merah;
    if (kata == "kuning") {
        lampu = Lampu::Kuning;
    } else if (kata == "hijau") {
        lampu = Lampu::Hijau;
    }
    switch (berikutnya(lampu)) {
        case Lampu::Merah: cout << "merah" << endl; break;
        case Lampu::Kuning: cout << "kuning" << endl; break;
        case Lampu::Hijau: cout << "hijau" << endl; break;
    }
    return 0;
}

