#include <iostream>
using namespace std;

bool lengkap(const int hitung[10]) {
    for (int d = 1; d <= 9; d++) {
        if (hitung[d] != 1) {
            return false;
        }
    }
    return true;
}

int main() {
    int g[9][9]{};
    for (auto &baris : g) {
        for (auto &sel : baris) {
            cin >> sel;
        }
    }
    auto sah = true;
    for (int a = 0; a < 9; a++) {
        int baris[10]{}, kolom[10]{}, kotak[10]{};
        for (int b = 0; b < 9; b++) {
            baris[g[a][b]]++;
            kolom[g[b][a]]++;
            kotak[g[a / 3 * 3 + b / 3][a % 3 * 3 + b % 3]]++;
        }
        if (!lengkap(baris) || !lengkap(kolom) || !lengkap(kotak)) {
            sah = false;
        }
    }
    if (sah) {
        cout << "sah" << endl;
    } else {
        cout << "tidak sah" << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int hitung(int baris, int n, int kolomRatu[]) {
    if (baris == n) {
        return 1;
    }
    auto banyak = 0;
    for (int k = 0; k < n; k++) {
        auto aman = true;
        for (int b = 0; b < baris; b++) {
            auto selisih = kolomRatu[b] - k;
            if (selisih == 0 || selisih == baris - b || selisih == b - baris) {
                aman = false;
            }
        }
        if (aman) {
            kolomRatu[baris] = k;
            banyak += hitung(baris + 1, n, kolomRatu);
        }
    }
    return banyak;
}

int main() {
    int n, kolom;
    cin >> n >> kolom;
    int kolomRatu[9]{};
    kolomRatu[0] = kolom - 1;
    cout << hitung(1, n, kolomRatu) << endl;
    return 0;
}
